\section{\textbf{PROJECT DESCRIPTION }}
\subsection{Chức năng}
\begin{itemize}
\item Giám sát trạng thái đèn LED và đo độ sáng: Hệ thống sử dụng cảm biến ánh sáng để giám sát mức độ sáng hiện tại. Đồng thời, nó cũng giám sát trạng thái bật/tắt của đèn LED.
\item Điều khiển đèn từ Internet: Người dùng có thể điều khiển trạng thái bật/tắt của đèn từ xa thông qua một ứng dụng trên Internet, có thể là Blynk, Thinkspeak hoặc Firebase.
\item Điều khiển đèn dựa trên thời gian và độ sáng: Hệ thống có thể tự động điều chỉnh trạng thái bật/tắt của đèn dựa trên thời gian và mức độ sáng hiện tại. Ví dụ, đèn có thể tự động bật vào buổi tối và tắt vào ban ngày, hoặc bật/tắt dựa trên ngưỡng độ sáng được đặt trước.
\end{itemize} 
\subsection{Yêu cầu}
\begin{itemize}
\item Lắp ráp và hoàn thành mạch cảm biến ánh sáng để giám sát mức độ ánh sáng.
\item Cảm biến ánh sáng cần đảm bảo độ chính xác cao để đo độ sáng môi trường một cách chính xác. 
\item Hệ thống cần có khả năng kết nối Internet để truyền dữ liệu và nhận lệnh điều khiển từ xa và từ ứng dụng Blynk, Thinkspeak hoặc Firebase.
\item Hệ thống cần hoạt động ổn định và đáng tin cậy, đảm bảo đèn điều khiển không gặp lỗi và sự cố.
\end{itemize} 

\section{\textbf{REQUIRED HARDWARE}}
\begin{enumerate}
    \item NodeMCU ESP8266
    \item Light Sensor
    \item MH-Real-Time Clock Module 2 
    \item LEDs (2)
    \item 220 ohm resitors (2)
    \item Bread Board
\end{enumerate}

