\begin{enumerate}
    \item  2 Đèn Led: 
        \begin{itemize}
             \item 2 đèn Led đồng thời kết nối với chân đất(GND) trong mạch NodeMCU.
              \item Chân còn lại của 2 bóng LED được kết nối với 2 điện trở: LED1 kết nối với điện trở R1(220 $\Omega$ )  và kết nối với chân D0. LED 2 kết nối với chân D1 thông qua điện trở R2(220   $\Omega$ ). Hai kết nối này có tác dụng cung cấp nguồn điện cho đèn và đèn được bật tắt dựa trên sự điều khiển của mạch NodeMCU esp8266.
        \end{itemize}
    \item Cảm Biến Anh Sáng: 
        \begin{itemize}
            \item Các chân cơ bản được nối vào GND và nguồn 3.3V để cung cấp nguồn điện cho cảm biến hoạt động.
            \item Một chân A0 trên NodeMCU kết nối với cảm biến ánh sáng, cho phép cảm biến ánh sáng cường độ ánh sáng của môi trường xung quanh rồi gửi tín hiệu về cho mạch NodeMCU xử lý.
        \end{itemize}
    \item Module Đồng Hồ Thời Gian Thực DS1302:
        \begin{itemize}
            \item VCC của module kết nối với Nguồn 3.3V của NodeMCU. GND tương tự được nối với GND của NodeMCU.
            \item CLK(Clock) được kết nối với chân D5 của Node MCU, có tác dụng như dây đồng hồ, điều khiển tốc độ truyền dữ liệu giữa module DS1302 và NodeMCU.
            \item DAT(data) được kết nối với chân D6 của Node MCU, có tác dụng truyền để NodeMCU gửi yêu cầu cũng như DS1302 trả lại thông tin dữ liệu (thời gian thực) cho mạch NodeMCU xử lý.
            \item RST( Reset): Nối với chân D7 của Node MCU, cho phép Node MCU khởi đồng lại module DS1302 khi cần thiết.
        \end{itemize}
    \item NodeMCU ESP8266:
        \begin{itemize}
            \item Ngoài các chân trên, NodeMCU có một cổng micro USB port để kết nối vào máy tính, laptop nhằm cho phép người dùng nạp code vào mạch NodeMCU để xử lý các tác vụ
        \end{itemize}


\end{enumerate}

